def test_case(pred_sqls, sol_sqls, db_path, conn, conditions):
    # Setup data - insert some test cards
    result1, exec_err1, timeout_err1 = execute_queries(
        ["INSERT INTO card (loan_id, type, issued) VALUES (4959, 'gold', '2000-09-03'), (4961, 'classic', '1997-09-03'), (4962, 'platinum', '1995-09-03');"], 
        db_path, conn, logger=None
    )
    if exec_err1 or timeout_err1:
        raise AssertionError("Setup query 1 failed")

    test_cases = [
            {
                "query": "INSERT INTO card (loan_id, type, issued) VALUES (4959, 'GOLD', '2024-01-01')",
                "should_fail": True,
                "error_message": "it should fail because the loan_id is already in the card table"
            },

            {
                "query": "INSERT INTO card (loan_id, type, issued) VALUES (999999, 'GOLD', '2024-01-01')",
                "should_fail": True,
                "error_message": "it should fail because the loan_id is not in the loan table"
            },

            {
                "query": "DELETE FROM loan WHERE loan_id = 4959",
                "should_fail": False,
                "verification_query": "SELECT COUNT(*) FROM card WHERE loan_id = 4959",
                "expected_count": 0,
                "error_message": "it should be 0 because the loan_id was deleted"
            },

            {
                "query": "DELETE FROM card WHERE loan_id = 4961",
                "should_fail": False,
                "verification_query": "SELECT loan_id FROM loan WHERE loan_id = 4961",
                "expected_result": "exists",
                "error_message": "loan should still exist because deleting card should not affect loan"
            }
        ]

    for test_case_item in test_cases:
            result, exec_err, timeout_err, error_msg = execute_queries(
                [test_case_item["query"]], db_path, conn, logger=None, return_error=True
            )

            if exec_err or timeout_err:
                if test_case_item["should_fail"]:
                    # Expected failure - check error message contains expected text
                    assert test_case_item["error_message"] in error_msg or error_msg != "", (
                        f"{test_case_item['error_message']}"
                    )
                else:
                    raise AssertionError(f"Unexpected error: {error_msg}")
            else:
                # Query succeeded
                if test_case_item["should_fail"]:
                    assert False, f"{test_case_item['error_message']}"

                if "verification_query" in test_case_item:
                    verify_result, verify_exec_err, verify_timeout_err = execute_queries(
                        [test_case_item["verification_query"]], db_path, conn, logger=None
